  "micro_lecture": {
    "duration_minutes": 10,
    "key_terms": [
      {
        "term": "Operator de comparatie",
        "definition": "Un bloc care compară doua valori și răspunde ADEVARAT sau FALS",
        "analogy": "E ca o întrebare cu raspuns da/nu: 'Este 5 mai mare ca 3?' - Da!"
      },
      {
        "term": "Mai mic (<)",
        "definition": "Verifică dacă prima valoare e mai mica decat a doua",
        "analogy": "3 < 7 e ADEVARAT, 10 < 5 e FALS"
      },
      {
        "term": "Mai mare (>)",
        "definition": "Verifică dacă prima valoare e mai mare decat a doua",
        "analogy": "8 > 2 e ADEVARAT, 4 > 9 e FALS"
      },
      {
        "term": "Egal (=)",
        "definition": "Verifică dacă cele doua valori sunt identice",
        "analogy": "5 = 5 e ADEVARAT, 5 = 7 e FALS"
      },
      {
        "term": "Bloc hexagonal",
        "definition": "Forma speciala (ca un scut) pentru condiții - se pune în blocuri 'dacă'",
        "analogy": "E ca o piesa de puzzle cu forma diferită - intra doar în locuri speciale"
      },
      {
        "term": "Condiție",
        "definition": "O expresie care e fie adevărată, fie falsa - baza deciziilor",
        "analogy": "E ca un semafor: verde (adevarat) sau rosu (fals)"
      }
    ],
    "explain_like_im_12": "Imaginati-va ca sunteti arbitru la un meci. La final intrebati: 'Scorul echipei A este mai mare decat al echipei B?' Dacă DA, echipa A castiga. Dacă NU, fie echipa B castiga, fie e egal. În Scratch, operatorii de comparatie fac exact acest lucru - compară doua valori și răspund DA sau NU.",
    "visual_aids": [
      "Tabel cu cei 3 operatori: < (mai mic), > (mai mare), = (egal)",
      "Captura Scratch: blocuri hexagonale verzi",
      "Diagrama: bloc 'dacă' cu condiție hexagonala inauntru"
