        "teacher_support": "Demonstreaza cum se pune variabilă în blocul de comparatie"
      },
      {
        "task": "Comparatie pentru egalitate - ghiceste numarul",
        "steps": [
          "Creează variabilă 'numar_secret' și seteaz-o la 7",
          "Creează variabilă 'incercare' și seteaz-o la 0",
          "Adaugă 'când se apasă tasta [1]' -> 'seteaza incercare la 1'",
          "Adaugă mai multe taste pentru numerele 2-9 (sau doar câteva)",
          "Adaugă 'când se apasă tasta [c]' (pentru verificare)",
          "Sub el: 'dacă <incercare = numar_secret> atunci' -> 'spune [Ai ghicit!]'",
          "Testeaza cu diferite numere"
        ],
        "teacher_support": "Subliniaza ca = verifică egalitatea, nu atribuie valoare"
      }
    ],
    "success_criteria": [
      "Elevul poate folosi blocul 'dacă' cu o condiție de comparatie",
      "Elevul înțelege diferenta dintre <, > și =",
      "Elevul poate compară variabile, nu doar numere fixe"
    ]
  },
  "practice_independent": {
