      "performanta": [
        {
          "task": "Creează un comparator de note: variabile 'nota1' și 'nota2'. Programul compară notele și spune: 'Nota 1 e mai mare', 'Nota 2 e mai mare' sau 'Notele sunt egale'. Folosește 3 blocuri 'dacă'.",
          "expected_output": "Toate cele 3 cazuri funcționează corect"
